-- 420_lde_drax_trei_reguli.sql — Drăxlmaier §8.5 + §8.7: «rămâne la uzină» scoasă, rămân 3 reguli de optimizare
-- (Ion, 28.09.2026: «scoate regula 2 în general, fă în 3 reguli»; ION-120). Gard de intrare: textul de după 419 (32752 / 50038da2804decc680563712949f49bc).
BEGIN;
DO $$
DECLARE n int; t text;
BEGIN
  UPDATE lde_uzine SET reguli_livrare = replace(replace(reguli_livrare, $v0$8.7 CELE 4 REGULI DE OPTIMIZARE (Ion, 28.09.2026: «1. Auto la capăt de rută rămâne dacă ruta se termină în aceeași localitate; 2. Auto rămâne la uzină; 3. Rutele împărțite altfel; 4. Nu pleacă acasă între schimburi»; dezbaterea Claude + Codex ION-120, 3 runde, Codex 10/10; deciziile lui Ion din 28.09). Fiecare km e într-o singură regulă, după bucata lui din §5. (1) DOARME LA CAPĂT: marginile nopții (livrarea de seară și de dimineață, fără golul impus) când ultimul retur al zilei se termină la capătul X (≤ 1,5 km) și primul tur de a doua zi pleacă din același X, iar mașina doarme la peste 2,5 km de X. Se propune mașinii doar peste 100 km pe săptămână (Ion: «depends on weekly»), cu distanța șoferului alături; naveta șoferului nu se numără (5.10). Nopțile în Bălți (7.4) și weekendul nu intră (Ion: «no»), se arată separat. Între schimburi nu există caz: turul schimbului 2 vine înaintea returului schimbului 1. (2) RĂMÂNE LA UZINĂ: între turul și returul aceleiași ture, toți km-ii din afara zonei uzinei (peste 3 km de porți și de parc), fără condițiile și fără plafonul din 8.3 (Ion, 28.09: «ok»). (3) RUTE ÎMPĂRȚITE ALTFEL: schimbul complet al atribuirii săptămânale între două mașini, după regulile 1, 2 și 4; costul de azi = km GPS ai marginilor rămase, costul după schimb = drumul pe șosea (Valhalla) de la locul nopții celeilalte mașini. Se propune doar dacă totalul flotei scade cu cel puțin 50 km pe săptămână (Ion: «if 1 bus is doing more and other less — what is the point?») și doar între mașini cu toate zilele măsurate; locurile pe tip de mașină lipsesc din bază, deci schimbul rămâne condiționat până la confirmarea lor. (4) NU PLEACĂ ACASĂ ÎNTRE SCHIMBURI: ocolul pe acasă între curse (5.2: cât lungește casa drumul); mașina așteaptă la capătul cursei următoare (tur) sau la uzină (retur). Săptămâna 14–20.09: regula 1 = 528 km măsurat (628 extrapolat, 4 mașini), 2 = 186 (222), 4 = 2.713 (3.225), împreună 3.428 (4.075) km pe săptămână; regula 3 = niciun schimb; nopțile în Bălți separat 474 (563). Pe pagină: blocul «Cele 4 reguli de optimizare», pe flotă și pe mașină. Indicațiile pentru dispecer (§12) nu se schimbă până la «da»-ul lui Ion.$v0$, $n0$8.7 CELE 3 REGULI DE OPTIMIZARE (Ion, 28.09.2026: «1. Auto la capăt de rută rămâne dacă ruta se termină în aceeași localitate; 2. Auto rămâne la uzină; 3. Rutele împărțite altfel; 4. Nu pleacă acasă între schimburi»; dezbaterea Claude + Codex ION-120, 3 runde, Codex 10/10; apoi Ion, după prima publicare: «scoate regula 2 în general, fă în 3 reguli» — «rămâne la uzină» nu se mai propune și nu intră în total). Fiecare km e într-o singură regulă, după bucata lui din §5. (1) DOARME LA CAPĂT: marginile nopții (livrarea de seară și de dimineață, fără golul impus) când ultimul retur al zilei se termină la capătul X (≤ 1,5 km) și primul tur de a doua zi pleacă din același X, iar mașina doarme la peste 2,5 km de X. Se propune mașinii doar peste 100 km pe săptămână (Ion: «depends on weekly»), cu distanța șoferului alături; naveta șoferului nu se numără (5.10). Nopțile în Bălți (7.4) și weekendul nu intră (Ion: «no»), se arată separat. Între schimburi nu există caz: turul schimbului 2 vine înaintea returului schimbului 1. (2) RUTE ÎMPĂRȚITE ALTFEL: schimbul complet al atribuirii săptămânale între două mașini, după regulile 1 și 3; costul de azi = km GPS ai marginilor rămase, costul după schimb = drumul pe șosea (Valhalla) de la locul nopții celeilalte mașini. Se propune doar dacă totalul flotei scade cu cel puțin 50 km pe săptămână (Ion: «if 1 bus is doing more and other less — what is the point?») și doar între mașini cu toate zilele măsurate; locurile pe tip de mașină lipsesc din bază, deci schimbul rămâne condiționat până la confirmarea lor. (3) NU PLEACĂ ACASĂ ÎNTRE SCHIMBURI: ocolul pe acasă între curse (5.2: cât lungește casa drumul); mașina așteaptă la capătul cursei următoare (tur) sau la uzină (retur). Săptămâna 14–20.09: regula 1 = 528 km măsurat (628 extrapolat, 4 mașini), 3 = 2.713 (3.225), împreună 3.241 (3.853) km pe săptămână; regula 2 = niciun schimb; nopțile în Bălți separat 474 (563). Pe pagină: blocul «Cele 3 reguli de optimizare», pe flotă și pe mașină. Indicațiile pentru dispecer (§12) nu se schimbă până la «da»-ul lui Ion.$n0$), $v1$8.5 Realocarea rutelor între mașini se socotește ca regula 3 din §8.7$v1$, $n1$8.5 Realocarea rutelor între mașini se socotește ca regula 2 din §8.7$n1$)
   WHERE id = 'DRAXELMAIER_BALTI' AND length(reguli_livrare) = 32752 AND md5(reguli_livrare) = '50038da2804decc680563712949f49bc';
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION '420: textul din bază nu e cel de după 419, rânduri: %', n; END IF;
  SELECT reguli_livrare INTO t FROM lde_uzine WHERE id = 'DRAXELMAIER_BALTI';
  IF length(t) <> 32653 OR md5(t) <> 'e83d5f226e01cb64031de63a580cc4f1' THEN RAISE EXCEPTION '420: text neașteptat (lungime %, md5 %)', length(t), md5(t); END IF;
END $$;
COMMIT;
